								74 => array (
										'id' => 13881,
										'name' => 'Cradle of the Worm Colossus',
										'icon' => '/esoui/art/icons/housing_cradleofthewormcolossus001.dds',
										'desc' => 'Discovered by guild mages in the aftermath of the Writhing Wall campaign, this dread realm hosts a bone colossus personally crafted by Wormblood. Wrest this stronghold from the worms and use the colossus to practice your best combat moves!',
										'type' => 19,
										'image' => '/esoui/art/store/pc_collections_hsg_cradleofthewormcolossus_1x1.dds',
										'nickname' => 'Writhing Plane Hold' 
								),
								75 => array (
										'id' => 13882,
										'name' => 'Druidspring Conservatory',
										'icon' => '/esoui/art/icons/housing_druidspringconservatory001.dds',
										'desc' => 'Experience all of Y`ffre`s seasons in a single day! This estate blends a Druid-crafted four-season garden and the beauty of a Breton`s noble villa. Grab a trowel and start making this garden getaway your own!',
