								19 => array (
										'id' => 13750,
										'name' => 'Dragonstar Elk',
										'icon' => '/esoui/art/icons/mount_dragonstarstripedelk.dds',
										'desc' => 'From the time they`re born, these elk have a strong sweet tooth. This is at odds with their imposing antlers and intimidating appearance, but the Orcs of the Dragontail Mountains use it to their advantage, easily training them with treats and food.',
										'type' => 2,
										'image' => '/esoui/art/icons/icon_missing.dds',
										'nickname' => 'Sleeker' 
								),
								20 => array (
										'id' => 13829,
										'name' => 'Warrior Wave Antelope',
										'icon' => '/esoui/art/icons/mount_ragadaantelope.dds',
										'desc' => '\"Honor your ancestors. He who permits their words and deeds to languish breaks his own blade and casts it to the burning wind.\"—Plea for Open Eyes',
										'type' => 2,
										'image' => '/esoui/art/icons/icon_missing.dds',
										'nickname' => 'Grazer' 
